#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int,int> pii;

const int N = 205;
const int M = N * N;

int read() { int x; cin >> x; return x; }

int head[2*N], nxt[M], to[M], cap[M], ec;
int prev_edge[M]; // not used

void add_edge(int u, int v, int uv, int vu) {
    nxt[ec] = head[u]; to[ec] = v; cap[ec] = uv; head[u] = ec++;
    nxt[ec] = head[v]; to[ec] = u; cap[ec] = vu; head[v] = ec++;
}

int max_flow(int s, int t) {
    int flow = 0;
    while (true) {
        vector<int> dist(2*N, -1);
        vector<int> parent(2*N, -1);
        vector<int> pedge(2*N, -1);
        queue<int> q;
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int e = head[v]; e != -1; e = nxt[e]) {
                if (cap[e] > 0 && dist[to[e]] == -1) {
                    dist[to[e]] = dist[v] + 1;
                    parent[to[e]] = v;
                    pedge[to[e]] = e;
                    q.push(to[e]);
                }
            }
        }
        if (dist[t] == -1) break;
        int f = 1e9;
        for (int v = t; v != s; v = parent[v]) {
            int e = pedge[v];
            f = min(f, cap[e]);
        }
        for (int v = t; v != s; v = parent[v]) {
            int e = pedge[v];
            cap[e] -= f;
            cap[e^1] += f;
        }
        flow += f;
    }
    return flow;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    int n = read(), dt = read();
    memset(head, -1, sizeof head);
    int a[N][N] = {{0}}, b[N][N] = {{0}};
    bool red[N][N] = {{false}}, block[N][N] = {{false}};
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            char c; cin >> c;
            if (c == 'Y') block[x][y] = true;
            else if (c == 'Z') red[x][y] = true;
            else a[x][y] = c - '0';
        }
    }
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            char c; cin >> c;
            if (c != 'Y' && c != 'Z') b[x][y] = c - '0';
        }
    }
    int m = n*n;
    int dis[N*N][N*N];
    for (int i=0; i<m; ++i) for (int j=0; j<m; ++j) dis[i][j] = (i==j?0:1000000000);
    int dx[4] = {0,-1,0,1};
    int dy[4] = {1,0,-1,0};
    for (int x=0; x<n; ++x) {
        for (int y=0; y<n; ++y) {
            if (block[x][y] || red[x][y]) continue;
            for (int d=0; d<4; ++d) {
                int i = x+dx[d], j = y+dy[d];
                if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j]) {
                    dis[x*n+y][i*n+j] = 1;
                }
            }
        }
    }
    for (int k=0; k<m; ++k)
        for (int i=0; i<m; ++i)
            for (int j=0; j<m; ++j)
                if (dis[i][k] + dis[k][j] < dis[i][j])
                    dis[i][j] = dis[i][k] + dis[k][j];
    int dred[N*N];
    for (int i=0; i<m; ++i) dred[i] = 1000000000;
    pii q[N*N];
    int h=0, t=0;
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            if (red[i][j]) {
                q[t++] = {i,j};
                dred[i*n+j] = 0;
            }
    while (h != t) {
        auto cur = q[h++];
        int x = cur.first, y = cur.second;
        for (int d=0; d<4; ++d) {
            int i = x+dx[d], j = y+dy[d];
            int id = i*n+j;
            if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j] && dred[id] > 1000000000) {
                dred[id] = dred[x*n+y] + 1;
                q[t++] = {i,j};
            }
        }
    }
    int source = N-2, sink = N-1;
    bool seen[N*N];
    for (int cur=0; cur<m; ++cur) {
        int sx = cur/n, sy = cur%n;
        if (block[sx][sy] || red[sx][sy]) continue;
        memset(seen, 0, sizeof seen);
        h = 0; t = 0;
        q[t++] = {sx,sy};
        seen[cur] = true;
        while (h != t) {
            auto p = q[h++];
            int x = p.first, y = p.second;
            int id = x*n+y;
            if (dis[cur][id] <= dt)
                add_edge(cur<<1, (id<<1)|1, 1000, 0);
            if (dis[cur][id] == dred[id]) continue;
            for (int d=0; d<4; ++d) {
                int i = x+dx[d], j = y+dy[d];
                int nid = i*n+j;
                if (i>=0 && i<n && j>=0 && j<n && !block[i][j] && !red[i][j] && dis[cur][nid] <= dred[nid] && dis[cur][nid] <= dt && dis[cur][nid] > dis[cur][id] && !seen[nid]) {
                    seen[nid] = true;
                    q[t++] = {i,j};
                }
            }
        }
    }
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            add_edge(source, (i*n+j)<<1, a[i][j], 0);
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            add_edge((i*n+j)<<1|1, sink, b[i][j], 0);
    cout << max_flow(source, sink);
    return 0;
}
